/**
 * Tearsheet — runtime
 *
 * Reads window.__PKTS_MANIFEST__ (injected by manifest.js, generated by
 * scripts/generate-manifest.mjs) and builds a single-page component playground.
 * Loaded as type="module" so it executes after dist/esm/bundle.js (which
 * registers the custom elements).
 *
 * Props form: schema-driven via renderForm() from form.js.
 * Code snippets: derived from state via serializers.js — never from DOM outerHTML.
 *   pkts-code elements are updated via setAttribute('code', …) and never recreated.
 *
 * Availability values:
 *   "html-native"  — no web component; native tags styled by Packets defaults.
 *   "ui-css"       — native element + pkts- class(es). Web component may exist.
 *   "web"          — web component only.
 *
 * Playground layout (applies to web and ui-css+web panels):
 *   <section class="ts2-playground">
 *     <div class="ts2-playground__preview">  preview sandbox (and CSS preview)  </div>
 *     <div class="ts2-playground__form">     props form + events + reset         </div>  ← omitted when no props
 *     <div class="ts2-playground__code">     web snippet (+ CSS snippet)         </div>
 *   </section>
 */

import { renderForm }             from '../form.js';
import { serializeWebComponent,
         serializeCss }           from './serializers.js';

// ── DOM helpers ───────────────────────────────────────────────────────────────

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'className') node.className = v;
    else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2).toLowerCase(), v);
    else node.setAttribute(k, v);
  }
  for (const child of children) {
    if (child == null) continue;
    node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return node;
}

/** Sync dark/palette classes from body to a preview container. */
function syncThemeClasses(container) {
  document.body.classList.forEach(cls => {
    if (cls === 'dark' || cls.startsWith('palette-')) container.classList.add(cls);
  });
}

// ── State helpers ─────────────────────────────────────────────────────────────

/**
 * Build the initial/default state from a component's props.
 * Union props seed to their first allowedValue; required string/number/boolean
 * props seed to canonical placeholders. Optional non-union props are not set.
 * Slot content is always seeded to '' so the key is present.
 */
function seedState(comp) {
  const state = {};
  for (const prop of comp.props) {
    if (prop.kind === 'event') continue;
    if (prop.kind === 'union' && prop.allowedValues?.length) {
      state[prop.attrName] = prop.allowedValues[0];
    } else if (!prop.optional) {
      if (prop.kind === 'string')   state[prop.attrName] = prop.name;
      else if (prop.kind === 'number')  state[prop.attrName] = '0';
      else if (prop.kind === 'boolean') state[prop.attrName] = false;
    }
  }
  if (comp.hasSlot) state['content'] = '';
  return state;
}

// ── Preview mounting ──────────────────────────────────────────────────────────

function applyPropToEl(el, prop, value) {
  if (value === null || value === undefined) {
    el.removeAttribute(prop.attrName);
    return;
  }
  if (prop.kind === 'boolean') {
    if (prop.booleanStyle === 'false-string') {
      el.setAttribute(prop.attrName, value ? 'true' : 'false');
    } else {
      if (prop.name in el) { try { el[prop.name] = !!value; return; } catch {} }
      el.toggleAttribute(prop.attrName, !!value);
    }
  } else {
    if (prop.name in el) { try { el[prop.name] = value; return; } catch {} }
    el.setAttribute(prop.attrName, String(value));
  }
}

function applyStateToEl(previewEl, comp, state) {
  for (const prop of comp.props) {
    if (prop.kind === 'event') continue;
    applyPropToEl(previewEl, prop, state[prop.attrName] ?? null);
  }
}

/** Update just the slot text of an existing preview element without recreating it. */
function applySlotToEl(previewEl, text) {
  // Find or create the first text node
  for (const node of previewEl.childNodes) {
    if (node.nodeType === Node.TEXT_NODE) {
      node.nodeValue = text;
      return;
    }
  }
  if (text) previewEl.insertBefore(document.createTextNode(text), previewEl.firstChild);
}

function createPreviewEl(comp) {
  if (comp.customElementExtends) {
    const e = document.createElement(comp.customElementExtends);
    e.setAttribute('is', comp.tagName);
    return e;
  }
  return document.createElement(comp.tagName);
}

/** Mount a fresh preview element into sandbox (called once per component). */
function mountPreview(sandbox, comp, state) {
  sandbox.innerHTML = '';
  const e = createPreviewEl(comp);
  const slotText = state['content'] ?? '';
  if (slotText) e.appendChild(document.createTextNode(slotText));
  sandbox.appendChild(e);
  applyStateToEl(e, comp, state);
  return e;
}

// ── Figma panel ───────────────────────────────────────────────────────────────

function buildFigmaPanel(figmaEntry, componentName) {
  const aside = document.createElement('aside');
  aside.className = 'demo-figma';

  const label = document.createElement('div');
  label.className = 'demo-label';
  label.textContent = 'Figma';

  const container = document.createElement('div');
  container.className = 'figma-embed';

  if (Array.isArray(figmaEntry.size) && figmaEntry.size.length === 2) {
    container.style.setProperty('--figma-ratio', String(figmaEntry.size[0] / figmaEntry.size[1]));
  }

  const iframe = document.createElement('iframe');
  iframe.src             = figmaEntry.url;
  iframe.title           = figmaEntry.title || `${componentName} in Figma`;
  iframe.loading         = 'lazy';
  iframe.allowFullscreen = true;

  container.appendChild(iframe);
  aside.append(label, container);
  return aside;
}

/** Wrap mainCol in a split grid with the Figma panel; returns mainCol. */
function buildSplitLayout(panel, comp) {
  const hasFigma = !!(comp.figma && comp.figma.url);
  if (hasFigma) {
    const split = document.createElement('div');
    split.className = 'ts-panel-split';
    const mainCol = document.createElement('div');
    mainCol.className = 'ts-panel-main';
    split.appendChild(mainCol);
    split.appendChild(buildFigmaPanel(comp.figma, comp.displayName));
    panel.appendChild(split);
    return mainCol;
  }
  return panel;
}

// ── Playground wrapper builder ────────────────────────────────────────────────

/**
 * Create the ts2-playground section and return its three region divs.
 * Regions that are null-ed out by the caller are not appended.
 *
 * @param {boolean} hasForm - whether a form region will be attached
 * @returns {{ playground, previewDiv, formDiv, codeDiv }}
 */
function buildPlayground(hasForm) {
  const playground = document.createElement('section');
  playground.className = 'ts2-playground';
  if (!hasForm) playground.classList.add('ts2-playground--no-form');

  const previewDiv = document.createElement('div');
  previewDiv.className = 'ts2-playground__preview';

  const codeDiv = document.createElement('div');
  codeDiv.className = 'ts2-playground__code';

  playground.appendChild(previewDiv);

  if (hasForm) {
    const formDiv = document.createElement('div');
    formDiv.className = 'ts2-playground__form';
    playground.appendChild(formDiv);
    playground.appendChild(codeDiv);
    return { playground, previewDiv, formDiv, codeDiv };
  }

  playground.appendChild(codeDiv);
  return { playground, previewDiv, formDiv: null, codeDiv };
}

// ── Component header ──────────────────────────────────────────────────────────

function buildHeader(comp) {
  const header = document.createElement('div');
  header.className = 'ts-comp-header';
  const title = document.createElement('h1');
  title.className = 'ts-comp-name';
  title.textContent = comp.displayName;
  header.appendChild(title);
  return header;
}

// ── Shared snippet-section helpers ────────────────────────────────────────────

function buildSnippetLabel(text) {
  const div = document.createElement('div');
  div.className = 'ts-snippet-label';
  div.textContent = text;
  return div;
}

function buildCodeEl() {
  const codeEl = document.createElement('pkts-code');
  codeEl.setAttribute('type', 'block');
  codeEl.setAttribute('language', 'html');
  return codeEl;
}

// ── HTML-native panel ─────────────────────────────────────────────────────────

function renderHtmlNativePanel(comp) {
  const panel = document.getElementById('ts-panel');
  panel.innerHTML = '';

  const header = buildHeader(comp);
  const note = document.createElement('p');
  note.className   = 'ts-css-note';
  note.textContent = 'Native HTML styled by Packets defaults. No web component or classes needed.';
  header.appendChild(note);
  panel.appendChild(header);

  if (comp.noDemo) {
    const nodemo = document.createElement('div');
    nodemo.className = 'ts-no-types';
    nodemo.innerHTML = `<strong>No demo available.</strong>&nbsp; Add an entry to <code>tearsheet/native-markup.json</code> to show a live preview.`;
    panel.appendChild(nodemo);
    return;
  }

  const mainCol = buildSplitLayout(panel, comp);

  const variants = comp.variants;
  let currentMarkup = variants ? variants[0].markup : (comp.markup || '');

  const { playground, previewDiv, codeDiv } = buildPlayground(/* hasForm */ !!(variants && variants.length > 1));

  // Preview sandbox
  const sandbox = document.createElement('div');
  sandbox.className = 'packets ts-preview';
  sandbox.dataset.preview = comp.id;
  syncThemeClasses(sandbox);
  previewDiv.appendChild(el('h6', { className: 'ts-section-title' }, 'Preview'));
  previewDiv.appendChild(sandbox);

  function renderMarkup() { sandbox.innerHTML = currentMarkup; }
  renderMarkup();

  // Variant form (if multiple variants)
  if (variants && variants.length > 1) {
    const variantSchema = {
      type: 'object',
      properties: {
        variant: {
          type: 'string',
          enum: variants.map(v => v.label),
          'x-kind': 'attribute',
          'x-attribute': 'variant',
          'x-inObserved': true,
        },
      },
      required: ['variant'],
    };
    const variantState = { variant: variants[0].label };
    const form = renderForm(variantSchema, variantState, (key, val) => {
      if (key !== 'variant') return;
      const v = variants.find(v => v.label === val);
      if (v) { currentMarkup = v.markup; renderMarkup(); updateSnippet(); }
    });
    const formDiv = playground.querySelector('.ts2-playground__form');
    if (formDiv) formDiv.appendChild(form);
  }

  // Code snippet
  const codeEl = buildCodeEl();
  codeEl.setAttribute('code', currentMarkup);
  codeDiv.appendChild(buildSnippetLabel('Code'));
  codeDiv.appendChild(codeEl);

  function updateSnippet() { codeEl.setAttribute('code', currentMarkup); }

  mainCol.appendChild(playground);
}

// ── ui-css (no web component) panel ──────────────────────────────────────────

function renderUiCssNoWebPanel(comp) {
  const panel = document.getElementById('ts-panel');
  panel.innerHTML = '';

  const header = buildHeader(comp);
  const note = document.createElement('p');
  note.className   = 'ts-css-note';
  note.textContent = 'Styled with pkts- classes on native HTML. No web component required.';
  header.appendChild(note);
  panel.appendChild(header);

  if (comp.noDemo) {
    const nodemo = document.createElement('div');
    nodemo.className = 'ts-no-types';
    nodemo.innerHTML = `<strong>No demo available.</strong>&nbsp; Add an entry to <code>tearsheet/native-markup.json</code> to show a live preview.`;
    panel.appendChild(nodemo);
    return;
  }

  const mainCol = buildSplitLayout(panel, comp);

  const variants = comp.variants;
  let currentMarkup = variants ? variants[0].markup : (comp.markup || '');

  const hasForm = !!(variants && variants.length > 1);
  const { playground, previewDiv, codeDiv } = buildPlayground(hasForm);

  // Variant select inside form region
  if (hasForm) {
    const variantRow = document.createElement('div');
    variantRow.className = 'ts-variant-row';
    const lbl = document.createElement('label');
    lbl.className   = 'ts-section-title';
    lbl.textContent = 'Variant';
    const sel = document.createElement('select');
    sel.className = 'ts-variant-select';
    variants.forEach((v, i) => {
      const o = document.createElement('option');
      o.value = String(i);
      o.textContent = v.label;
      sel.appendChild(o);
    });
    sel.addEventListener('change', () => {
      currentMarkup = variants[Number(sel.value)].markup;
      renderMarkup();
      updateSnippet();
    });
    variantRow.appendChild(lbl);
    variantRow.appendChild(sel);
    const formDiv = playground.querySelector('.ts2-playground__form');
    if (formDiv) formDiv.appendChild(variantRow);
  }

  // Preview sandbox
  const sandbox = document.createElement('div');
  sandbox.className = 'packets ts-preview';
  sandbox.dataset.preview = comp.id;
  syncThemeClasses(sandbox);
  previewDiv.appendChild(el('h2', { className: 'ts-section-title' }, 'Preview'));
  previewDiv.appendChild(sandbox);

  function renderMarkup() { sandbox.innerHTML = currentMarkup; }
  renderMarkup();

  // Code snippet
  const codeEl = buildCodeEl();
  codeEl.setAttribute('code', currentMarkup);
  codeDiv.appendChild(buildSnippetLabel('CSS classes'));
  codeDiv.appendChild(codeEl);

  function updateSnippet() { codeEl.setAttribute('code', currentMarkup); }

  mainCol.appendChild(playground);
}

// ── ui-css (with web component) panel ────────────────────────────────────────

function renderUiCssWebPanel(comp) {
  const panel = document.getElementById('ts-panel');
  panel.innerHTML = '';

  // Header
  const header = buildHeader(comp);
  const tagCode = document.createElement('code');
  tagCode.className   = 'ts-tag-name';
  tagCode.textContent = comp.customElementExtends
    ? `<${comp.customElementExtends} is="${comp.tagName}">`
    : `<${comp.tagName}>`;
  header.appendChild(tagCode);
  panel.appendChild(header);

  const mainCol = buildSplitLayout(panel, comp);

  const hasForm = !!(comp.hasTypesFile && comp.schema);
  const { playground, previewDiv, formDiv, codeDiv } = buildPlayground(hasForm);

  // No-types notice
  if (!comp.hasTypesFile) {
    const notice = document.createElement('div');
    notice.className = 'ts-no-types';
    notice.innerHTML =
      `<strong>No types file.</strong>&nbsp; Add <code>${comp.className}.types.ts</code> to get prop controls.`;
    previewDiv.appendChild(notice);
    if (comp.observedAttributes.length) {
      const attrs = document.createElement('p');
      attrs.className = 'ts-obs-attrs';
      attrs.innerHTML = `Observed attributes: ${comp.observedAttributes.map(a => `<code>${a}</code>`).join(', ')}`;
      previewDiv.appendChild(attrs);
    }
  }

  // Single state object — includes slot content under key 'content'
  const state        = seedState(comp);
  const defaultState = seedState(comp);  // kept for serializer default comparison

  // Web-component preview sandbox
  const sandbox = document.createElement('div');
  sandbox.className  = 'ts-preview';
  sandbox.dataset.preview = comp.tagName;
  previewDiv.appendChild(el('h2', { className: 'ts-section-title' }, 'Preview'));
  previewDiv.appendChild(sandbox);

  const previewEl = mountPreview(sandbox, comp, state);

  // Web component snippet
  const webCodeEl = buildCodeEl();
  webCodeEl.setAttribute('code', serializeWebComponent(comp, state, defaultState));

  // CSS snippet — driven by state via serializeCss
  const cssCodeEl = buildCodeEl();
  cssCodeEl.setAttribute('code', serializeCss(comp, state));

  // CSS preview — mirrors body dark/palette; set via textContent only
  const cssPreview = document.createElement('div');
  cssPreview.className = 'packets ts-css-preview';
  syncThemeClasses(cssPreview);
  cssPreview.innerHTML = comp.cssMarkup || '';

  function updateSnippets() {
    webCodeEl.setAttribute('code', serializeWebComponent(comp, state, defaultState));
    const cssHtml = serializeCss(comp, state);
    cssCodeEl.setAttribute('code', cssHtml);
    cssPreview.innerHTML = cssHtml;
  }

  // Props form
  if (hasForm) {
    const form = renderForm(comp.schema, state, (key, newVal) => {
      if (key === 'content') {
        // Update slot text in-place — do NOT recreate the preview element
        state['content'] = newVal ?? '';
        applySlotToEl(previewEl, state['content']);
      } else {
        const prop = comp.props.find(p => p.attrName === key || p.name === key);
        if (newVal === null || newVal === undefined) {
          delete state[key];
          if (prop) applyPropToEl(previewEl, prop, null);
          else previewEl.removeAttribute(key);
        } else {
          state[key] = newVal;
          if (prop) applyPropToEl(previewEl, prop, newVal);
          else previewEl.setAttribute(key, String(newVal));
        }
      }
      updateSnippets();
    });
    formDiv.appendChild(form);

    if (comp.events && comp.events.length) {
      const evtSection = document.createElement('div');
      evtSection.className = 'ts-events-list';
      const evtTitle = document.createElement('h3');
      evtTitle.className = 'ts-section-subtitle';
      evtTitle.textContent = 'Events';
      evtSection.appendChild(evtTitle);
      for (const evt of comp.events) {
        const row = document.createElement('div');
        row.className = 'ts-event-field';
        const lbl = document.createElement('span');
        lbl.className = 'ts-event-label';
        lbl.textContent = evt.name;
        row.appendChild(lbl);
        if (evt.description) {
          const desc = document.createElement('span');
          desc.className = 'ts-event-value';
          desc.textContent = evt.description;
          row.appendChild(desc);
        }
        evtSection.appendChild(row);
      }
      formDiv.appendChild(evtSection);
    }

    const resetBtn = document.createElement('pkts-button');
    resetBtn.setAttribute('label', 'Reset to defaults');
    resetBtn.setAttribute('variant', 'default');
    resetBtn.addEventListener('click', () => renderPanel(comp));
    formDiv.appendChild(resetBtn);
  }

  // Code region: web snippet then CSS snippet
  codeDiv.appendChild(buildSnippetLabel('Web component'));
  codeDiv.appendChild(webCodeEl);
  codeDiv.appendChild(buildSnippetLabel('CSS classes'));
  codeDiv.appendChild(cssCodeEl);
  codeDiv.appendChild(buildSnippetLabel('CSS preview'));
  codeDiv.appendChild(cssPreview);

  mainCol.appendChild(playground);
}

// ── Web-only panel ────────────────────────────────────────────────────────────

function renderWebPanel(comp) {
  const panel = document.getElementById('ts-panel');
  panel.innerHTML = '';

  // Header
  const header = buildHeader(comp);
  const tagCode = document.createElement('code');
  tagCode.className   = 'ts-tag-name';
  tagCode.textContent = comp.customElementExtends
    ? `<${comp.customElementExtends} is="${comp.tagName}">`
    : `<${comp.tagName}>`;
  header.appendChild(tagCode);
  panel.appendChild(header);

  const mainCol = buildSplitLayout(panel, comp);

  const hasForm = !!(comp.hasTypesFile && comp.schema);
  const { playground, previewDiv, formDiv, codeDiv } = buildPlayground(hasForm);

  // No-types notice
  if (!comp.hasTypesFile) {
    const notice = document.createElement('div');
    notice.className = 'ts-no-types';
    notice.innerHTML =
      `<strong>No types file.</strong>&nbsp; Add <code>${comp.className}.types.ts</code> to get prop controls.`;
    previewDiv.appendChild(notice);
    if (comp.observedAttributes.length) {
      const attrs = document.createElement('p');
      attrs.className = 'ts-obs-attrs';
      attrs.innerHTML = `Observed attributes: ${comp.observedAttributes.map(a => `<code>${a}</code>`).join(', ')}`;
      previewDiv.appendChild(attrs);
    }
  }

  // Single state object
  const state        = seedState(comp);
  const defaultState = seedState(comp);

  // Preview sandbox
  const sandbox = document.createElement('div');
  sandbox.className  = 'ts-preview';
  sandbox.dataset.preview = comp.tagName;
  previewDiv.appendChild(el('h2', { className: 'ts-section-title' }, 'Preview'));
  previewDiv.appendChild(sandbox);

  const previewEl = mountPreview(sandbox, comp, state);

  // Code snippet
  const codeEl = buildCodeEl();
  codeEl.setAttribute('code', serializeWebComponent(comp, state, defaultState));

  function updateSnippet() {
    codeEl.setAttribute('code', serializeWebComponent(comp, state, defaultState));
  }

  // Props form
  if (hasForm) {
    const form = renderForm(comp.schema, state, (key, newVal) => {
      if (key === 'content') {
        state['content'] = newVal ?? '';
        applySlotToEl(previewEl, state['content']);
      } else {
        const prop = comp.props.find(p => p.attrName === key || p.name === key);
        if (newVal === null || newVal === undefined) {
          delete state[key];
          if (prop) applyPropToEl(previewEl, prop, null);
          else previewEl.removeAttribute(key);
        } else {
          state[key] = newVal;
          if (prop) applyPropToEl(previewEl, prop, newVal);
          else previewEl.setAttribute(key, String(newVal));
        }
      }
      updateSnippet();
    });
    formDiv.appendChild(form);

    if (comp.events && comp.events.length) {
      const evtSection = document.createElement('div');
      evtSection.className = 'ts-events-list';
      const evtTitle = document.createElement('h3');
      evtTitle.className = 'ts-section-subtitle';
      evtTitle.textContent = 'Events';
      evtSection.appendChild(evtTitle);
      for (const evt of comp.events) {
        const row = document.createElement('div');
        row.className = 'ts-event-field';
        const lbl = document.createElement('span');
        lbl.className = 'ts-event-label';
        lbl.textContent = evt.name;
        row.appendChild(lbl);
        if (evt.description) {
          const desc = document.createElement('span');
          desc.className = 'ts-event-value';
          desc.textContent = evt.description;
          row.appendChild(desc);
        }
        evtSection.appendChild(row);
      }
      formDiv.appendChild(evtSection);
    }

    const resetBtn = document.createElement('pkts-button');
    resetBtn.setAttribute('label', 'Reset to defaults');
    resetBtn.setAttribute('variant', 'default');
    resetBtn.addEventListener('click', () => renderPanel(comp));
    formDiv.appendChild(resetBtn);
  }

  // Code region
  codeDiv.appendChild(el('h2', { className: 'ts-section-title' }, 'Code'));
  codeDiv.appendChild(codeEl);

  mainCol.appendChild(playground);
}

// ── Render component panel (dispatch) ─────────────────────────────────────────

function renderPanel(comp) {
  const avail = comp.availability;

  if (avail === 'html-native') {
    renderHtmlNativePanel(comp);
    return;
  }

  if (avail === 'ui-css') {
    if (comp.tagName) {
      renderUiCssWebPanel(comp);
    } else {
      renderUiCssNoWebPanel(comp);
    }
    return;
  }

  // 'web' or any unknown value
  renderWebPanel(comp);
}

// ── Sidebar ───────────────────────────────────────────────────────────────────

function buildSidebar(manifest) {
  const nav = document.getElementById('ts-nav');
  nav.innerHTML = '';

  const controlsRow = document.createElement('div');
  controlsRow.className = 'ts-sidebar-controls';

  const filterLabel = document.createElement('label');
  filterLabel.className   = 'ts-filter-label';
  filterLabel.htmlFor     = 'ts-avail-filter';
  filterLabel.textContent = 'Show:';

  const filterSel = document.createElement('select');
  filterSel.id        = 'ts-avail-filter';
  filterSel.className = 'ts-filter-select';
  for (const [val, text] of [
    ['all',         'All'],
    ['html-native', 'HTML native'],
    ['ui-css',      'ui-css'],
  ]) {
    const o = document.createElement('option');
    o.value = val;
    o.textContent = text;
    filterSel.appendChild(o);
  }

  controlsRow.appendChild(filterLabel);
  controlsRow.appendChild(filterSel);
  nav.appendChild(controlsRow);

  const catMap = new Map();
  for (const comp of manifest) {
    const cat = comp.category || 'Uncategorized';
    const sub = comp.subcategory || '';
    if (!catMap.has(cat)) catMap.set(cat, new Map());
    const subMap = catMap.get(cat);
    if (!subMap.has(sub)) subMap.set(sub, []);
    subMap.get(sub).push(comp);
  }

  for (const [cat, subMap] of catMap) {
    const details = document.createElement('details');
    details.className = 'ts-nav-cat';
    details.dataset.category = cat;

    const summary = document.createElement('summary');
    summary.className = 'ts-nav-cat-summary';
    summary.textContent = cat;
    details.appendChild(summary);

    for (const [sub, comps] of subMap) {
      const subgroup = document.createElement('div');
      subgroup.className = 'ts-nav-subgroup';
      subgroup.dataset.subcat = sub;

      if (sub) {
        const subLabel = document.createElement('div');
        subLabel.className = 'ts-nav-subcat';
        subLabel.textContent = sub;
        subgroup.appendChild(subLabel);
      }

      for (const comp of comps) {
        const avail = comp.availability || 'web';
        const a = document.createElement('a');
        a.href      = `#${comp.id || comp.tagName}`;
        a.className = 'ts-nav-item copy';
        a.dataset.tagName      = comp.id || comp.tagName;
        a.dataset.search       = comp.displayName.toLowerCase() + ' ' + (comp.id || comp.tagName);
        a.dataset.availability = avail;

        a.appendChild(document.createTextNode(comp.displayName));

        if (avail === 'html-native') {
          const chip = document.createElement('span');
          chip.className = 'ts-avail-chip ts-html-native-chip';
          chip.textContent = 'HTML native';
          a.appendChild(chip);
        } else if (avail === 'ui-css') {
          const chip = document.createElement('span');
          chip.className = 'ts-avail-chip ts-ui-css-chip';
          chip.textContent = 'ui-css';
          a.appendChild(chip);
        }

        subgroup.appendChild(a);
      }

      details.appendChild(subgroup);
    }

    nav.appendChild(details);
  }
}

// ── Active link + auto-expand ─────────────────────────────────────────────────

function setActiveLink(id) {
  document.querySelectorAll('.ts-nav-item').forEach(a => {
    const isActive = a.dataset.tagName === id;
    a.classList.toggle('ts-active', isActive);
    if (isActive) {
      const details = a.closest('details.ts-nav-cat');
      if (details) details.open = true;
      a.scrollIntoView({ block: 'nearest' });
    }
  });
}

// ── Search ────────────────────────────────────────────────────────────────────

function initSearch() {
  const input = document.getElementById('ts-search');
  if (!input) return;

  function applyVisibility() {
    const q      = input.value.trim().toLowerCase();
    const filter = document.getElementById('ts-avail-filter')?.value ?? 'all';

    document.querySelectorAll('.ts-nav-item').forEach(a => {
      const matchesSearch = !q || a.dataset.search.includes(q);
      const matchesFilter = filter === 'all' || a.dataset.availability === filter;
      a.classList.toggle('ts-hidden', !(matchesSearch && matchesFilter));
    });

    document.querySelectorAll('.ts-nav-subgroup').forEach(sg => {
      sg.style.display = sg.querySelectorAll('.ts-nav-item:not(.ts-hidden)').length > 0 ? '' : 'none';
    });

    document.querySelectorAll('.ts-nav-cat').forEach(details => {
      const anyVisible = details.querySelectorAll('.ts-nav-item:not(.ts-hidden)').length > 0;
      details.style.display = anyVisible ? '' : 'none';
      if (q && anyVisible) details.open = true;
    });
  }

  input.addEventListener('input', applyVisibility);

  const filterSel = document.getElementById('ts-avail-filter');
  if (filterSel) filterSel.addEventListener('change', applyVisibility);
}

// ── Router ────────────────────────────────────────────────────────────────────

function handleRoute(manifest) {
  const hash = location.hash.slice(1);
  const comp  = manifest.find(c => c.id === hash || c.tagName === hash) || manifest[0];
  if (!comp) return;
  renderPanel(comp);
  setActiveLink(comp.id || comp.tagName);
}

// ── Init ──────────────────────────────────────────────────────────────────────

const manifest = window.__PKTS_MANIFEST__;

if (!manifest) {
  document.getElementById('ts-panel').innerHTML = `
    <div class="ts-error">
      <h2>Manifest not found</h2>
      <p>Generate it first (from packages/ui-web):</p>
      <pre>npm run generate-manifest</pre>
      <p>Then reload this page.</p>
    </div>
  `;
} else {
  buildSidebar(manifest);
  initSearch();
  handleRoute(manifest);
  window.addEventListener('hashchange', () => handleRoute(manifest));

  if (typeof window.buildPalettePicker === 'function') {
    window.buildPalettePicker();
    window.applyPalette(localStorage.getItem('packets-palette') || 'default');
  }

  const toggle = document.getElementById('ts-theme-toggle');
  if (toggle) {
    const cb = toggle.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = document.body.classList.contains('dark');
    toggle.addEventListener('change', () => {
      if (typeof window.toggleTheme === 'function') window.toggleTheme();
      const cb2 = toggle.querySelector('input[type="checkbox"]');
      if (cb2) cb2.checked = document.body.classList.contains('dark');
    });
  }
}
